55	const PROCESSING_FEE = 5;
56	const BASE_PREMIUMS: Record<string, number> = {
57	  sword: 100,
58	  amulet: 60,
59	  staff: 80,
60	  potion: 40,
61	  rune: 25,
62	  moonstone: 25,
63	};
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_PREMIUM = 60;
67	
68	const isBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE;
70	
71	const basePremiumOfItem = (item: Item): number => BASE_PREMIUMS[item.type];
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + basePremiumOfItem(item), 0);
75	
76	const groupByType = (items: Item[]): Item[][] =>
77	  Object.values(
78	    items.reduce<Record<string, Item[]>>(
79	      (groups, item) => ({
80	        ...groups,
81	        [item.type]: [...(groups[item.type] ?? []), item],
82	      }),
83	      {},
84	    ),
85	  );
86	
87	const basePremiumOfGroup = (items: Item[]): number =>
88	  isBlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
89	
90	const policyBasePremium = (items: Item[]): number =>
91	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
92	
93	const CURSED_SURCHARGE_RATE = 0.5;
94	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
95	
96	const HIGH_ENCHANTMENT_THRESHOLD = 5;
97	
98	const isCursed = (item: Item): boolean => item.cursed === true;
99	
100	const UNENCHANTED = 0;
101	
102	const enchantmentOf = (item: Item): number => item.enchantment ?? UNENCHANTED;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	const NO_SURCHARGE_RATE = 0;
108	
109	const surchargeRateOfItem = (item: Item): number =>
110	  (isCursed(item) ? CURSED_SURCHARGE_RATE : NO_SURCHARGE_RATE) +
111	  (isHighlyEnchanted(item)
112	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
113	    : NO_SURCHARGE_RATE);
114	
115	const surchargeOfItem = (item: Item): number =>
116	  basePremiumOfItem(item) * surchargeRateOfItem(item);
117	
118	const sumOfItemSurcharges = (items: Item[]): number =>
119	  items.reduce((sum, item) => sum + surchargeOfItem(item), 0);
120	
121	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
122	
123	const firstInsuranceSurcharge = (basePremium: number): number =>
124	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
125	
126	const roundPremiumInMHPCOsFavour = (premium: number): number =>
127	  Math.ceil(premium);
128	
129	const LOYALTY_DISCOUNT_RATE = 0.2;
130	const LOYALTY_YEARS_THRESHOLD = 2;
131	const NO_DISCOUNT = 0;
132	
133	const isLoyal = (customer: Customer): boolean =>
134	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
135	
136	const loyaltyDiscount = (customer: Customer, basePremium: number): number =>
137	  isLoyal(customer) ? basePremium * LOYALTY_DISCOUNT_RATE : NO_DISCOUNT;
138	
139	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
140	
141	const isFollowUpContract = (previousQuoteCount: number): boolean =>
142	  previousQuoteCount > 0;
143	
144	const followUpContractDiscount = (
145	  previousQuoteCount: number,
146	  basePremium: number,
147	): number =>
148	  isFollowUpContract(previousQuoteCount)
149	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
150	    : NO_DISCOUNT;
151	
152	const quote = (
153	  items: Item[],
154	  customer: Customer,
155	  previousQuoteCount: number,
156	): QuoteResult => {
157	  const basePremium = policyBasePremium(items);
158	  const surcharges =
159	    sumOfItemSurcharges(items) + firstInsuranceSurcharge(basePremium);
160	  const discounts =
161	    loyaltyDiscount(customer, basePremium) +
162	    followUpContractDiscount(previousQuoteCount, basePremium);
163	  return {
164	    premium: roundPremiumInMHPCOsFavour(
165	      PROCESSING_FEE + basePremium + surcharges - discounts,
166	    ),
167	  };
168	};
