180	const FULL_REIMBURSEMENT_RATE = 1;
181	
182	const damagedItem = (damage: Damage, policyItems: Item[]): Item =>
183	  policyItems.find((item) => item.type === damage.itemType)!;
184	
185	const isDeeplyEnchanted = (item: Item): boolean =>
186	  enchantmentOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
187	
188	const reimbursementRateOfItem = (item: Item): number =>
189	  isDeeplyEnchanted(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
190	
191	const payoutOfDamage = (damage: Damage, policyItems: Item[]): number =>
192	  damage.amount * reimbursementRateOfItem(damagedItem(damage, policyItems)) -
193	  DEDUCTIBLE;
194	
195	const payoutOfIncident = (incident: Incident, policyItems: Item[]): number =>
196	  incident.damages.reduce(
197	    (sum, damage) => sum + payoutOfDamage(damage, policyItems),
198	    0,
199	  );
200	
201	const insuranceSum = (items: Item[]): number =>
202	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
203	
204	const capOfPolicy = (policyItems: Item[]): number =>
205	  CAP_FACTOR * insuranceSum(policyItems);
206	
207	const claim = (incident: Incident, policyItems: Item[]): ClaimResult => {
208	  const payout = payoutOfIncident(incident, policyItems);
209	  return {
210	    payout,
211	    remainingCap: capOfPolicy(policyItems) - payout,
212	  };
213	};
214	
215	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
216	
217	const quoteSteps = (steps: Step[]): QuoteStep[] => steps.filter(isQuoteStep);
218	
219	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] =>
220	  quoteSteps(steps)[policy].items;
221	
222	const quoteCountBefore = (steps: Step[], stepIndex: number): number =>
223	  quoteSteps(steps.slice(0, stepIndex)).length;
224	
225	export const runScenario = (scenario: Scenario): ScenarioResult => ({
226	  results: scenario.steps.map((step, stepIndex) =>
227	    isQuoteStep(step)
228	      ? quote(
229	          step.items,
230	          scenario.customer,
231	          quoteCountBefore(scenario.steps, stepIndex),
232	        )
233	      : claim(step.incident, insuredItemsOfPolicy(scenario.steps, step.policy)),
234	  ),
235	});
